CREATE TABLE "HostSalarySchedule" ("effectiveFrom" TIMESTAMP(3) PRIMARY KEY, tiers JSONB NOT NULL);
CREATE TABLE "HostSalaryControl" (id TEXT PRIMARY KEY, "noticeEnabled" BOOLEAN NOT NULL DEFAULT true, "nextCloseStart" TIMESTAMP(3) NOT NULL);
CREATE TABLE "HostSalaryAward" ("cycleStart" TIMESTAMP(3) NOT NULL, "userId" TEXT NOT NULL REFERENCES "User"(id), level INTEGER NOT NULL, earned BIGINT NOT NULL, "rewardDiamonds" BIGINT NOT NULL, "agencyShares" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("cycleStart","userId"));
INSERT INTO "HostSalaryControl" VALUES ('global',true,date_trunc('month',timezone('UTC',now())) + CASE WHEN extract(day from timezone('UTC',now()))>=16 THEN interval '15 days' ELSE interval '0 days' END);
-- If an existing host reporting policy uses calendar months, anchor to its actual boundary.
UPDATE "HostSalaryControl" SET "nextCloseStart"=date_trunc('month',"nextCloseStart")
WHERE (SELECT days FROM "ReportingCyclePolicy" WHERE module='HOST_SALARY' AND "effectiveFrom"<=timezone('UTC',now()) ORDER BY "effectiveFrom" DESC LIMIT 1)=30;
INSERT INTO "HostSalarySchedule" SELECT "nextCloseStart", '[{"level":1,"target":450000,"percent":1,"reward":0,"vip":0,"days":0},{"level":2,"target":900000,"percent":1,"reward":0,"vip":0,"days":0},{"level":3,"target":1350000,"percent":3,"reward":0,"vip":0,"days":0},{"level":4,"target":2250000,"percent":3,"reward":0,"vip":0,"days":0},{"level":5,"target":5400000,"percent":4,"reward":150000,"vip":1,"days":3},{"level":6,"target":8100000,"percent":4,"reward":150000,"vip":1,"days":5},{"level":7,"target":10350000,"percent":6,"reward":200000,"vip":1,"days":7},{"level":8,"target":13500000,"percent":6,"reward":250000,"vip":2,"days":3},{"level":9,"target":20250000,"percent":7,"reward":400000,"vip":2,"days":5},{"level":10,"target":24750000,"percent":7,"reward":500000,"vip":3,"days":7},{"level":11,"target":47250000,"percent":9,"reward":900000,"vip":3,"days":10},{"level":12,"target":60750000,"percent":9,"reward":1250000,"vip":3,"days":14},{"level":13,"target":74250000,"percent":10,"reward":1500000,"vip":4,"days":7},{"level":14,"target":101700000,"percent":10,"reward":2000000,"vip":4,"days":10},{"level":15,"target":115200000,"percent":12,"reward":2250000,"vip":4,"days":14},{"level":16,"target":135000000,"percent":12,"reward":2500000,"vip":4,"days":21},{"level":17,"target":160200000,"percent":13,"reward":3000000,"vip":5,"days":10},{"level":18,"target":202500000,"percent":13,"reward":4000000,"vip":5,"days":15},{"level":19,"target":236700000,"percent":15,"reward":4500000,"vip":5,"days":21},{"level":20,"target":337500000,"percent":15,"reward":6500000,"vip":5,"days":30}]'::jsonb FROM "HostSalaryControl";
ALTER TYPE "WalletTransactionType" ADD VALUE IF NOT EXISTS 'HOST_SALARY_REWARD';
INSERT INTO "ReportingCyclePolicy"(id,module,days,revision,"effectiveFrom","createdById")
SELECT 'salary-launch-'||m,m,15,1,"nextCloseStart",'SYSTEM' FROM "HostSalaryControl",unnest(ARRAY['HOST_SALARY','AGENCY_COMMISSION']) AS m
WHERE NOT EXISTS(SELECT 1 FROM "ReportingCyclePolicy" p WHERE p.module=m);
